<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';requireModuleAccess('customer_orders');
$id=(int)($_GET['id']??0);$q=$conn->prepare("SELECT o.*,c.customer_name,c.phone,c.address,s.invoice_number,s.sale_date FROM customer_sales_orders o JOIN customers c ON c.id=o.customer_id LEFT JOIN sales s ON s.id=o.sale_id WHERE o.id=? AND o.status='Invoiced'");$q->execute([$id]);$o=$q->fetch();if(!$o){http_response_code(404);exit('Confirmed invoice not found.');}
$q=$conn->prepare("SELECT i.*,p.product_name,p.unit FROM customer_sales_order_items i JOIN products p ON p.id=i.product_id WHERE i.order_id=? ORDER BY i.id");$q->execute([$id]);$items=$q->fetchAll();$company=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='company_name' LIMIT 1")->fetchColumn()?:'Dibonke Bookshop');$currency=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='currency' LIMIT 1")->fetchColumn()?:'KES');
?><!doctype html><html><head><meta charset="utf-8"><title><?=e($o['invoice_number'])?></title><style>body{font-family:Arial,sans-serif;color:#172b43;margin:30px}.invoice{max-width:850px;margin:auto;padding:35px;border:1px solid #ddd}.head{display:flex;justify-content:space-between;gap:20px}.muted{color:#64748b}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e5e7eb}.num{text-align:right}.actions{text-align:center;margin:20px}@media print{.actions{display:none}.invoice{border:0;padding:0}body{margin:0}}</style></head><body><div class="actions"><button onclick="window.print()">Print Invoice</button> <a href="index.php">Orders</a></div><article class="invoice"><div class="head"><div><h1><?=e($company)?></h1><h2>Customer Invoice</h2><strong><?=e($o['customer_name'])?></strong><br><?=e($o['phone']??'')?><br><?=e($o['address']??'')?></div><div class="num"><h2><?=e($o['invoice_number'])?></h2><p><?=e($o['sale_date'])?></p><p>Order: <?=e($o['order_number'])?></p><strong>PAYMENT DUE</strong></div></div><table><thead><tr><th>Product</th><th>Quantity</th><th>Unit Price</th><th class="num">Amount</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['product_name'])?></td><td><?=e($it['entered_quantity'])?> <?=e($it['sale_unit'])?></td><td><?=e($currency)?> <?=number_format((float)$it['entered_unit_price'],2)?></td><td class="num"><?=e($currency)?> <?=number_format((float)$it['subtotal'],2)?></td></tr><?php endforeach;?></tbody></table><div class="num"><p>Subtotal: <?=e($currency)?> <?=number_format((float)$o['subtotal'],2)?></p><p>VAT: <?=e($currency)?> <?=number_format((float)$o['tax'],2)?></p><h2>Total Due: <?=e($currency)?> <?=number_format((float)$o['total_amount'],2)?></h2></div><p class="muted">Thank you for your business.</p></article></body></html>
